import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import * as esbuild from "esbuild";

const root = path.dirname(fileURLToPath(import.meta.url));
const outputName = "phala-sdk-runtime-capsule-0.4.0-0.5.8.mjs";
const sha256 = (bytes) => `sha256:${createHash("sha256").update(bytes).digest("hex")}`;
const read = (file) => fs.readFileSync(path.join(root, file));
const sorted = (value) => Array.isArray(value) ? value.map(sorted)
  : value && typeof value === "object"
    ? Object.fromEntries(Object.keys(value).sort().map((key) => [key, sorted(value[key])]))
    : value;
const json = (value) => `${JSON.stringify(sorted(value), null, 2)}\n`;

assert.equal(process.version, "v24.9.0");
assert.equal(esbuild.version, "0.28.1");
for (const [name, version] of Object.entries({
  "@phala/cloud": "0.4.0",
  "@phala/dstack-sdk": "0.5.8",
  "@noble/curves": "1.9.7",
  "@noble/hashes": "1.8.0",
  viem: "2.55.4",
  zod: "3.25.76",
})) {
  assert.equal(JSON.parse(read(`node_modules/${name}/package.json`)).version, version);
}

const options = {
  absWorkingDir: root,
  entryPoints: ["capsule-entry.mjs"],
  outfile: outputName,
  alias: {
    debug: "./debug-stub.mjs",
    mitt: "./mitt-stub.mjs",
    ofetch: "./ofetch-stub.mjs",
  },
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node24",
  treeShaking: true,
  legalComments: "external",
  metafile: true,
  write: false,
  logLevel: "silent",
};

// Two independent compiler invocations must produce identical generated bytes.
const first = await esbuild.build(options);
const second = await esbuild.build(options);
assert.equal(first.outputFiles.length, second.outputFiles.length);
for (let index = 0; index < first.outputFiles.length; index += 1) {
  assert.equal(first.outputFiles[index].path, second.outputFiles[index].path);
  assert.deepEqual(first.outputFiles[index].contents, second.outputFiles[index].contents);
}
assert.deepEqual(first.metafile, second.metafile);
const output = first.outputFiles.find((file) => path.basename(file.path) === outputName);
assert.ok(output);
const source = output.text;
assert.equal(sha256(output.contents), "sha256:05ea7afcbf02ff779fc85a50765a95d2007286ec0dc6f686ef2e2636d45f34c0",
  "rebuilt capsule differs from the reviewed SDK 0.4.0 artifact");
const builtinImports = [...source.matchAll(
  /^\s*import\s+(?:[^"']+?\s+from\s+)?["']([^"']+)["'];?\s*$/gmu,
)].map((match) => match[1]).sort();
assert.deepEqual(builtinImports, ["crypto", "node:crypto"]);
for (const forbidden of [
  /\b(?:fetch|XMLHttpRequest|WebSocket)\b/u,
  /\b(?:eval|Function)\b/u,
  /\bWebAssembly\b/u,
  /\bprocess\s*(?:\.|\[|\?\.)/u,
  /\bimport\s*\(/u,
  /\brequire\s*\(/u,
  /\b__require\s*\(/u,
  /\b(?:Deno|Bun)\s*(?:\.|\[)/u,
  /["'](?:node:)?(?:child_process|cluster|dgram|dns|fs|http|https|module|net|tls|vm|worker_threads)["']/u,
  /\.node(?:["'`]|\b)/u,
]) assert.equal(forbidden.test(source), false, `forbidden capsule capability ${forbidden}`);

const graph = first.metafile.outputs[outputName];
assert.ok(graph);
const contributingInputs = Object.entries(graph.inputs)
  .filter(([, value]) => value.bytesInOutput > 0)
  .map(([name]) => name).sort();
const components = new Map();
for (const name of contributingInputs) {
  if (!name.startsWith("node_modules/")) continue;
  let directory = path.dirname(path.join(root, name));
  let manifest;
  while (directory !== root) {
    const manifestPath = path.join(directory, "package.json");
    if (fs.existsSync(manifestPath)) {
      const candidate = JSON.parse(fs.readFileSync(manifestPath));
      if (typeof candidate.name === "string" && typeof candidate.version === "string") {
        manifest = candidate;
        break;
      }
    }
    directory = path.dirname(directory);
  }
  assert.notEqual(directory, root, `package ownership unavailable for ${name}`);
  const key = `${manifest.name}@${manifest.version}`;
  if (components.has(key)) continue;
  const licenseNames = fs.readdirSync(directory).filter((entry) => /^(?:license|notice)(?:\..*)?$/iu.test(entry)).sort();
  assert.ok(licenseNames.some((entry) => /^license/iu.test(entry)), `license missing for ${key}`);
  components.set(key, {
    name: manifest.name,
    version: manifest.version,
    license: manifest.license,
    texts: licenseNames.map((entry) => ({
      filename: entry,
      text: fs.readFileSync(path.join(directory, entry), "utf8"),
    })),
  });
}
const componentNames = [...components.keys()].sort();
const generatedLegal = first.outputFiles.find((file) => file.path.endsWith(".LEGAL.txt"))?.text ?? "";
const legalText = [
  "THIRD-PARTY SOFTWARE NOTICES",
  "",
  "Candidate only: mechanically bundled and tree-shaken SDK actions. SDK-owned",
  "debug, event, and HTTP imports are replaced with capability-restricting stubs.",
  "No active release authority is conferred by this generated candidate.",
  "",
  ...componentNames.flatMap((name) => [name, "-".repeat(name.length), ...components.get(name).texts.flatMap(({ filename, text }) => [filename, text.trimEnd(), ""])]),
  generatedLegal.trimEnd(),
  "",
].join("\n");
const outputDirectory = path.join(root, "build");
assert.equal(sha256(legalText), "sha256:47d8d6cae4719c8b6703d27e02ce507eaef1eba5c080c583e2a8367a132ed335",
  "rebuilt notices differ from the reviewed artifact");
fs.mkdirSync(outputDirectory, { recursive: true, mode: 0o700 });
fs.writeFileSync(path.join(outputDirectory, outputName), output.contents);
fs.writeFileSync(path.join(outputDirectory, `${outputName}.LEGAL.txt`), legalText);
fs.writeFileSync(path.join(outputDirectory, "metafile.json"), json(first.metafile));
const material = {
  schema: "dnai.phala-sdk-migration-candidate-build.v1",
  truth_status: "isolated_local_reproducible_candidate_not_active_release_or_launch_authority",
  capsule: { filename: outputName, sha256: sha256(output.contents), byte_length: output.contents.length, builtin_imports: builtinImports, exports: graph.exports },
  legal_notice: { sha256: sha256(legalText), byte_length: Buffer.byteLength(legalText), components: componentNames },
  build: { node_version: process.version, esbuild_version: esbuild.version, two_independent_builds_identical: true, resolved_input_graph_count: Object.keys(first.metafile.inputs).length, contributing_input_count: contributingInputs.length, package_lock_sha256: sha256(read("package-lock.json")) },
  source_files: Object.fromEntries([
    "node_modules/@phala/cloud/package.json", "node_modules/@phala/cloud/dist/index.mjs",
    "node_modules/@phala/dstack-sdk/package.json", "node_modules/@phala/dstack-sdk/dist/get-compose-hash.mjs",
    "node_modules/@phala/dstack-sdk/dist/encrypt-env-vars.mjs", "node_modules/@phala/dstack-sdk/dist/verify-env-encrypt-public-key.mjs",
  ].map((name) => [name, { sha256: sha256(read(name)), byte_length: read(name).length }])),
  contributing_inputs: Object.fromEntries(contributingInputs.map((name) => [name, sha256(read(name))])),
};
fs.writeFileSync(path.join(outputDirectory, "candidate-build.json"), json(material));
console.log(json({ capsule: material.capsule, build: material.build, legal_notice: material.legal_notice }));
